<?php
declare(strict_types=1);
namespace Modules\Integrations;
use App\{Auth,DB,Http,View};

final class TemplateView
{
    public static function page(string $channel): string {
        Auth::requirePermission('messaging.write');$actor=Auth::user();if(!in_array($actor['role'],['director','admin'],true))throw new \RuntimeException('Недостаточно прав',403);if(!in_array($channel,['max','email','top'],true))throw new \RuntimeException('Страница не найдена',404);$e=Support::e(...);$db=DB::pdo();$title=['max'=>'Шаблоны MAX','email'=>'Шаблоны Email','top'=>'Шаблоны верхних уведомлений'][$channel];$body=View::heading($title,$channel==='top'?'Изменяются заголовок и текст. Цвет, условия появления, получатели и время показа 10 секунд сохраняются.':'Изменения применяются к новым уведомлениям. Сохранение шаблона не отправляет сообщения.');if(!empty($_GET['result']))$body.='<p class="registry-ui-secondary" role="status">'.$e($_GET['result']).'</p>';$q=$db->prepare('SELECT * FROM integration_template_catalog WHERE channel=? ORDER BY source_key');$q->execute([$channel]);$entries=$q->fetchAll(\PDO::FETCH_ASSOC);$body.='<section class="table-card registry-ui-card"><div class="table-scroll"><table class="table registry-ui-table registry-ui-compact-table registry-ui-compact-table--weight-single"><thead><tr><th scope="col">Событие</th><th scope="col">Действие</th><th scope="col">Условия показа</th></tr></thead><tbody>';foreach($entries as $t)$body.='<tr><td>'.$e($t['name']).'</td><td><a class="btn btn-toolbar" href="?edit='.rawurlencode($t['source_key']).'">Изменить</a></td><td><span class="registry-ui-modal-text">'.$e($t['trigger_text']).'</span><span class="registry-ui-modal-help">Версия: '.$e($t['version']).'.</span></td></tr>';if(!$entries)$body.='<tr><td colspan="3">Каталог ещё не получен из подтверждённого источника.</td></tr>';$body.='</tbody></table></div></section>';
        if(isset($_GET['edit'])){$key=(string)$_GET['edit'];$entry=null;foreach($entries as $t)if($t['source_key']===$key)$entry=$t;if(!$entry)throw new \RuntimeException('Шаблон не найден',404);$fields='';if($channel==='top')$fields.='<label class="field"><span class="field-label">Заголовок <span class="req">*</span></span><input class="field-input" name="title" value="'.$e($entry['title']).'" maxlength="80" required></label>';elseif($channel==='email')$fields.='<label class="field"><span class="field-label">Тема письма <span class="req">*</span></span><input class="field-input" name="subject" value="'.$e($entry['subject']).'" maxlength="200" required></label>';else {$fields.='<label class="field"><span class="field-label">Формат</span><select class="field-select" name="format" id="template-format">';foreach(['plain'=>'Обычный текст','markdown'=>'Markdown','html'=>'HTML'] as $v=>$label)$fields.='<option value="'.$v.'"'.($entry['format']===$v?' selected':'').'>'.$label.'</option>';$fields.='</select></label>';}$fields.='<label class="field"><span class="field-label">'.($channel==='top'?'Текст уведомления':'Текст сообщения').' <span class="req">*</span></span><textarea class="field-textarea" id="template-body" name="body" rows="6" maxlength="'.($channel==='top'?600:4000).'" required>'.$e($entry['body_text']).'</textarea></label>';
            $body.='<dialog class="modal registry-ui-modal registry-ui-modal--reading ui-detail-card" id="template-editor" aria-labelledby="template-title"><form method="post" action="/integrations/catalog-save" class="registry-ui-modal-form"><input type="hidden" name="_csrf" value="'.$e(Http::csrf()).'"><input type="hidden" name="channel" value="'.$channel.'"><input type="hidden" name="source_key" value="'.$e($key).'"><input type="hidden" name="expected_version" value="'.$e($entry['version']).'"><div class="modal-head"><h2 class="modal-title" id="template-title">Шаблон уведомления · '.$e($entry['name']).'</h2><button class="modal-close" type="button" data-dialog-close aria-label="Закрыть">×</button></div><div class="modal-body registry-ui-modal-grid"><div class="demo-value-pair"><span class="registry-ui-secondary">Когда показывается</span><span class="registry-ui-modal-text">'.$e($entry['trigger_text']).'</span><span class="registry-ui-secondary">Действующая версия</span><span class="registry-ui-modal-text">'.$e($entry['version']).'</span></div>'.$fields.'<span class="registry-ui-modal-help">Подстановки: '.$e(implode(', ',array_map(static fn($v)=>'{'.$v.'}',$channel==='top'?TemplateCatalog::TOP_VARS:TemplateCatalog::MESSAGE_VARS))).'.</span><section class="registry-ui-modal-grid" aria-label="Предпросмотр уведомления"><span class="registry-ui-modal-summary">Предпросмотр</span><div id="template-preview" aria-live="polite"></div><span class="registry-ui-modal-help" id="template-preview-error" role="alert" hidden></span></section><span class="registry-ui-modal-help">Изменения применяются к новым уведомлениям; история сохраняется.</span></div><div class="modal-foot"><div class="modal-foot-actions"><button type="button" class="btn btn-secondary" data-dialog-close>Отмена</button><button class="btn btn-primary" type="submit">Сохранить</button></div></div></form></dialog>';
            $json=htmlspecialchars(Support::json(['channel'=>$channel,'name'=>$entry['name']]),ENT_NOQUOTES|ENT_SUBSTITUTE,'UTF-8');$body.='<script src="/integrations/ui/notification-templates.js"></script><script>document.getElementById("template-editor").showModal();const channel='.Support::scriptJson($channel).';const field=document.getElementById("template-body"),format=document.getElementById("template-format"),out=document.getElementById("template-preview"),error=document.getElementById("template-preview-error");const api=globalThis.RentalNotificationTemplates;let editor;if(channel==="max"){editor=api.mountEditor(field,{format:format.value,values:{text:"Документ направлен на проверку.",number:"173",party:"Контрагент",actor:"Исполнитель",context:"Договор №173"}});format.addEventListener("change",()=>editor.setFormat(format.value));}function refresh(){try{if(channel==="top"){const title=document.querySelector("[name=title]");const values={title:"Изменения сохранены",text:"Документ направлен на проверку.",record:"Договор №173",section:"Согласования",why:"Требуется проверка.",actor:"Исполнитель",number:"2",party:"Контрагент",template:'.Support::scriptJson($entry['name']).',details:"Помещение 204"};out.replaceChildren();for(const text of [title.value,field.value]){const node=document.createElement("div");node.textContent=text.replace(/\{([^{}]+)\}/g,(_,k)=>values[k]??"");out.append(node);}}else if(channel==="email"){const subject=document.querySelector("[name=subject]");const value=api.renderEmail({subject:subject.value,body:field.value},{text:"Документ направлен на проверку.",number:"173",party:"Контрагент",context:"Договор №173"});out.replaceChildren();for(const text of [value.subject,value.body]){const node=document.createElement("div");node.textContent=text;out.append(node);}}else{api.previewInto(out,format.value,api.render(format.value,field.value,{text:"Документ направлен на проверку.",number:"173",party:"Контрагент",actor:"Исполнитель",context:"Договор №173"}));}error.hidden=true;}catch(e){out.replaceChildren();error.textContent=e.message;error.hidden=false;}}document.querySelectorAll("#template-editor input,#template-editor textarea,#template-editor select").forEach(el=>el.addEventListener("input",refresh));refresh();</script>';
        }
        return View::page($title,$body,'templates-'.$channel);
    }
    public static function save(): never {if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST')throw new \RuntimeException('Требуется POST',405);Http::checkCsrf();Auth::requirePermission('messaging.write');$actor=Auth::user();if(!in_array($actor['role'],['director','admin'],true))throw new \RuntimeException('Недостаточно прав',403);$channel=(string)($_POST['channel']??'');$key=(string)($_POST['source_key']??'');$fields=$channel==='max'?['format','body']:($channel==='email'?['subject','body']:['title','body']);$input=[];foreach($fields as $name)$input[$name]=(string)($_POST[$name]??'');try{$r=(new TemplateCatalog(DB::pdo(),Config::store()))->save($channel,$key,(int)($_POST['expected_version']??0),$input,$actor['name']);\App\Audit::record('notification.template.saved',$channel,$key,null,['version'=>$r['version']]);$notice='Шаблон сохранён. Сообщение не отправлялось.';}catch(\Throwable $e){$notice=$e->getMessage()==='REVISION_CONFLICT'?'Версия шаблона изменилась. Откройте актуальную редакцию.':'Шаблон не сохранён. Проверьте текст, формат и подстановки.';}Http::redirect('/connection-templates-'.$channel.'?result='.rawurlencode($notice));}
    public static function asset(): never {Auth::requirePermission('messaging.write');header('Content-Type: application/javascript; charset=utf-8');header('X-Content-Type-Options: nosniff');readfile(__DIR__.'/ui/notification-templates.js');exit;}
}
